from collections import defaultdict
def comps(g,bg):
    H,W=len(g),len(g[0]); seen=[[0]*W for _ in range(H)]; out=[]
    for y in range(H):
        for x in range(W):
            if seen[y][x] or g[y][x]==bg: continue
            c=g[y][x]; st=[(y,x)]; seen[y][x]=1; cl=[]
            while st:
                cy,cx=st.pop(); cl.append((cy,cx))
                for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=cy+dy,cx+dx
                    if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and g[ny][nx]==c:
                        seen[ny][nx]=1; st.append((ny,nx))
            out.append((c,cl))
    return out
def norm(cl):
    ys=[y for y,x in cl]; xs=[x for y,x in cl]
    return tuple(sorted((y-min(ys),x-min(xs)) for y,x in cl))
