def isLshape(sh):
    s=set(sh); n=len(sh)
    for (cy,cx) in sh:
        v=[y for y in range(max(y for y,x in sh)+1) if (y,cx) in s]
        h=[x for x in range(max(x for y,x in sh)+1) if (cy,x) in s]
        if len(v)+len(h)-1==n and s<=set([(y,cx) for y in v])|set([(cy,x) for x in h]):
            v.sort(); h.sort()
            if all(v[i+1]-v[i]==1 for i in range(len(v)-1)) and all(h[i+1]-h[i]==1 for i in range(len(h)-1)):
                return True
    return False
