def side(cl, mk):
    s=set(mk[1])
    ys=[y for y,x in mk[1]]; xs=[x for y,x in mk[1]]
    # find corner and arm directions
    for (cy,cx) in mk[1]:
        v=sorted(y for y in range(max(ys)+1) if (y,cx) in s)
        h=sorted(x for x in range(max(xs)+1) if (cy,x) in s)
        if len(v)+len(h)-1==len(mk[1]):
            vd = +1 if v[-1]>cy else -1   # vertical arm direction
            hd = +1 if h[-1]>cx else -1
            # inside quadrant = (y-cy)*vd>0 and (x-cx)*hd>0
            my=sum(y for y,x in cl)/len(cl); mx=sum(x for y,x in cl)/len(cl)
            return ((my-cy)*vd>0) and ((mx-cx)*hd>0)
